private void btn_Export_Mau1_Click(object sender, EventArgs e)
{
    if (!rdoShowType2.Checked)
    {
        MessageManager.Warning("Vui lòng chọn chế độ xem Chi tiết phiếu trước khi xuất!");
        return;
    }

    bool? bolIsRealOutput = null;
    DataTable dtbExport = GetOutputVoucherSearchParams(out bolIsRealOutput);
    if (dtbExport == null || dtbExport.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    string strFileName = Application.StartupPath + "/Template/StockManager/Voucher/Mau1_ChiTietXuat_BT.xlsx";
    string timeStamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");

    string strFileNamSaveAs = Application.StartupPath
        + "/Export/" + timeStamp + "_Mau1_ChiTietXuat_BT.xlsx";

    Hashtable hstColumns = new Hashtable();
    Hashtable hstValues = new Hashtable();

    string[] cols = { "Outputvoucherdetailid", "OutputDate", "ItemName", "can_tong", "can_bi", "Quantity", "UnitWeight", "QuantityM3" };
    foreach (string col in cols)
        hstColumns.Add(col, col);

    if (Libs.CExcel.ExportTemplateExcel(dtbExport, strFileName, "Outputvoucherdetailid", hstColumns, hstValues, strFileNamSaveAs))
        System.Diagnostics.Process.Start(strFileNamSaveAs);
    else
        ErrorManager.Error("Xuất dữ liệu thất bại!");
}

